//! Boba Job Find — Tauri core entry point.
//!
//! Registers every MVP plugin so later slices do not edit this file
//! (backlog ownership convention 8): single-instance (AD-18), tray (feature),
//! notification, autostart, global-shortcut, log, updater + process.
//! Commands and events are registered in [`ipc::command_list`] (AD-3).

mod autostart;
mod commands;
pub mod events;
pub mod ipc;
mod lifecycle;
mod notifications;
mod scheduler;
mod shortcuts;
mod tray;
pub mod wiring;

/// Build and run the desktop application.
#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    // Typed IPC: one specta Builder drives the invoke handler and the events (AD-3).
    let ipc = ipc::builder();

    let builder = tauri::Builder::default()
        .invoke_handler(ipc.invoke_handler())
        // Must be the first plugin registered. A second launch lands on the
        // running window instead of starting again (S1.6, AC3).
        .plugin(tauri_plugin_single_instance::init(|app, argv, cwd| {
            lifecycle::on_second_instance(app, argv, cwd);
        }))
        .plugin(tauri_plugin_notification::init())
        // A login launch carries `--autostart` (S5.4, FR-44): that is how the
        // app starts in the tray with no window instead of showing it.
        .plugin(
            tauri_plugin_autostart::Builder::new()
                .arg(autostart::LOGIN_ARG)
                .build(),
        )
        .plugin(tauri_plugin_global_shortcut::Builder::new().build())
        .plugin(tauri_plugin_log::Builder::new().build())
        .plugin(tauri_plugin_dialog::init())
        .plugin(tauri_plugin_opener::init())
        .plugin(tauri_plugin_window_state::Builder::default().build());

    #[cfg(desktop)]
    let builder = builder.plugin(tauri_plugin_process::init());

    builder
        .setup(move |app| {
            use tauri::Manager;

            // Mount typed events and register cancellable-task state (AD-3).
            ipc.mount_events(app);
            app.manage(events::TaskRegistry::default());

            // Composition root (ADR-012): open the store and mount its ports.
            wiring::mount(app.handle());

            #[cfg(desktop)]
            {
                use tauri::tray::TrayIconBuilder;

                // One in-core tray (AD-18). The icon is created here so later
                // slices extend tray behavior without editing lib.rs (AC8);
                // menu and behavior belong to S1.6.
                let mut tray = TrayIconBuilder::with_id("boba-tray");
                if let Some(icon) = app.default_window_icon() {
                    tray = tray.icon(icon.clone());
                }
                tray.build(app)?;

                // The menu, close-to-tray and the tray actions (S1.6) live in
                // `lifecycle`; this one call keeps later slices out of this file.
                lifecycle::install(app.handle());

                app.handle()
                    .plugin(tauri_plugin_updater::Builder::new().build())?;
            }
            Ok(())
        })
        .run(tauri::generate_context!())
        .expect("error while running Boba Job Find");
}
